#include <stdio.h>
#include <string.h>

void normalize(const char *src, char *dst, int allow_star) {
    int j = 0;
    for (int i = 0; src[i] != '\0'; ) {
        unsigned char c = (unsigned char)src[i];
        if (c == '*' && allow_star) {
            dst[j++] = '*';
            i++;
        } else if (c >= 'a' && c <= 'z') {
            dst[j++] = c;
            i++;
        } else if (c == 0xC3) {
            unsigned char next = (unsigned char)src[i + 1];
            char base = 0;
            switch (next) {
                case 0xA1: case 0xA0: case 0xA2: case 0xA3: case 0xA4: case 0xA5: base = 'a'; break;
                case 0xA9: case 0xA8: case 0xAA: case 0xAB: base = 'e'; break;
                case 0xAD: case 0xAC: case 0xAE: case 0xAF: base = 'i'; break;
                case 0xB3: case 0xB2: case 0xB4: case 0xB5: case 0xB6: base = 'o'; break;
                case 0xBA: case 0xB9: case 0xBB: case 0xBC: base = 'u'; break;
                case 0xA7: base = 'c'; break;
                default: base = 0; break;
            }
            if (base) dst[j++] = base;
            i += 2;
        } else if (c >= 0xE0 && c <= 0xFC) {
            char base = 0;
            switch (c) {
                case 0xE1: case 0xE0: case 0xE2: case 0xE3: case 0xE4: case 0xE5: base = 'a'; break;
                case 0xE9: case 0xE8: case 0xEA: case 0xEB: base = 'e'; break;
                case 0xED: case 0xEC: case 0xEE: case 0xEF: base = 'i'; break;
                case 0xF3: case 0xF2: case 0xF4: case 0xF5: case 0xF6: base = 'o'; break;
                case 0xFA: case 0xF9: case 0xFB: case 0xFC: base = 'u'; break;
                case 0xE7: base = 'c'; break;
                default: base = 0; break;
            }
            if (base) dst[j++] = base;
            i++;
        } else {
            i++;
        }
    }
    dst[j] = '\0';
}

int main() {
    char P[1024], A[1024];
    if (scanf("%s", P) != 1) return 0;
    if (scanf("%s", A) != 1) return 0;

    char normP[1024], normA[1024];
    normalize(P, normP, 0);
    normalize(A, normA, 1);

    int cnt[26] = {0};
    for (int i = 0; normP[i]; i++) {
        cnt[normP[i] - 'a']++;
    }

    int ok = 1;
    for (int i = 0; normA[i]; i++) {
        if (normA[i] == '*') continue;
        int idx = normA[i] - 'a';
        if (idx < 0 || idx >= 26 || cnt[idx] == 0) {
            ok = 0;
            break;
        }
        cnt[idx]--;
    }

    printf("%c\n", ok ? 'S' : 'N');
    return 0;
}
